#pragma once
template<class Check> void smartDiveChecks(Check check){
 using namespace ff3Assist;
 ff3Play::Scene scene;scene.valid=scene.focused=true;scene.typing=scene.menu=false;scene.pid=1;scene.model=2;scene.own=3;scene.player=4;scene.at=10;scene.head={0,10,0};scene.rootPosition={0,8,0};scene.groundY=0;scene.velocity={0,0,25};scene.worldGravity=196.2;scene.speed=22;scene.standingRootHeight=3.5;scene.cameraForward={0,0,1};ContactReach hand{{},1.25,true};
 ff3qb::BallObservation ball{100,{0,10,10},{},196.2,false,99,true};
 auto smart=plannedDiveTarget(scene,ball,10,40,8,25,hand,true,true,{0,0,1});
 check(smart.valid&&smart.catchable&&smart.requiredExtra>0&&smart.requiredExtra<=8,"Smart Boost selects a catchable future contact inside its extra-distance cap");
 check(!plannedDiveTarget(scene,ball,10,40,2,25,hand,true,true,{0,0,1}).valid,"Smart Boost rejects a catch requiring more than its limit instead of clamping an unreachable attempt");
 DistanceDive control;check(control.begin(scene.rootPosition,scene.velocity,smart,10,true,true,smart.requiredExtra,40,true,diveAirWindow(scene)),"Smart Boost uses the computed budget rather than the slider maximum");auto first=control.sample(scene.rootPosition,scene.velocity,10,smart);check(first.valid&&control.budget==smart.requiredExtra&&control.budget<=8&&first.velocity.z>25,"Smart Boost issues the required initial extra speed within its selected budget");
 {Vec position=scene.rootPosition,velocity=first.velocity;double extraTravel=0,elapsed=0;while(elapsed<smart.eta){const double dt=std::min(.004,smart.eta-elapsed);position=position+flat(velocity)*dt;extraTravel+=std::max(0.,ff3qb::length(flat(velocity))-25)*dt;elapsed+=dt;auto command=control.sample(position,velocity,10+elapsed,smart);check(command.valid,"Smart Boost remains valid throughout its planned contact interval");velocity=command.velocity;if(command.complete)break;}const auto contact=position+flat(velocity)*std::max(0.,smart.eta-elapsed);check(distance(contact,smart.point)<hand.radius&&extraTravel<=control.budget+.05,"simulated Smart Boost reaches its selected contact using only its computed extra-distance budget");}
 {auto boosted=scene;boosted.velocity={0,0,90};auto refreshed=plannedDiveTarget(boosted,ball,10,40,8,25,hand,true,false,{0,0,1});check(refreshed.valid&&refreshed.requiredExtra>5,"Smart Boost refresh does not mistake its own 90-stud command for permanent natural dive speed");}
 auto crossing=ball;crossing.position={0,10,-6};crossing.velocity={0,0,65};auto ahead=plannedDiveTarget(scene,crossing,10,40,8,25,hand,false,true,{0,0,1});check(ahead.valid&&ahead.point.z>0&&ahead.catchable,"a pass moving from behind to ahead targets a reachable forward contact rather than reversing the dive");
 crossing.position.z=-15;auto missed=plannedDiveTarget(scene,crossing,10,40,0,25,hand,false,true,{0,0,1});check(!missed.valid,"an uncatchable pass behind the dive cannot trigger a backwards Approach or landing redirect");
 auto normal=distanceDiveTarget(scene,ball,10,40,8,25,hand);auto guarded=plannedDiveTarget(scene,ball,10,40,8,25,hand,false,true,{0,0,1});check(normal.valid&&guarded.valid&&distance(normal.point,guarded.point)<.001,"already-forward manual Assist keeps its working target");
 auto close=smart;close.at=10.06;close.eta=.06;DistanceDive manual;check(manual.begin(scene.rootPosition,scene.velocity,close,10,false,true,7,40,false,.4)&&std::abs(manual.until-10.4)<1e-8,"manual Boost lasts through the airborne window rather than ending with an early 60 ms intercept estimate");
 scene.looseBalls={{101,{1,.6,0},{},28,false,99,true},ball};auto selected=closestDiveBall(scene,true,40);check(selected&&selected->id==100,"a nearby resting football cannot steal the active pass's dive target");check(!closestDiveBall(scene,true,5),"a live pass outside the shared target limit does not redirect the dive to an unrelated floor ball");
 auto lowered=ContactReach{{-.35,-2.3,-1.8},.95,true};auto raised=raisedCatchContact(lowered,{1,2,1},{2,1,1});check(raised.anticipated&&raised.radius==lowered.radius&&raised.offset.y>2,"Interception planning anticipates lifting measured hands instead of planning around a lowered catch part");check(!raisedCatchContact({{0,2.3,0},.95,true},{1,2,1},{2,1,1}).anticipated,"an already raised measured catch pose stays measured");
}
